using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API at the given path.")]
    public static async Task<string> FetchApi(
        IHttpClientFactory httpClientFactory,
        [Description("The API endpoint path, e.g. /users/1")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Target style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"Summarize the following text in a {style} style:\n\n{text}"
                }
            }
        ];
    }
}

